func (nbq *NubanBankQuery) loadBlacklist(ctx context.Context, query *NubanBlacklistQuery, nodes []*NubanBank, init func(*NubanBank), assign func(*NubanBank, *NubanBlacklist)) error {
	fks := make([]driver.Value, 0, len(nodes))
	nodeids := make(map[string]*NubanBank)
	for i := range nodes {
		fks = append(fks, nodes[i].ID)
		nodeids[nodes[i].ID] = nodes[i]
		if init != nil {
			init(nodes[i])
		}
	}
	if len(query.ctx.Fields) > 0 {
		query.ctx.AppendFieldOnce(nubanblacklist.FieldNubanBankID)
	}
	query.Where(predicate.NubanBlacklist(func(s *sql.Selector) {
		s.Where(sql.InValues(s.C(nubanbank.BlacklistColumn), fks...))
	}))
	neighbors, err := query.All(ctx)
	if err != nil {
		return err
	}
	for _, n := range neighbors {
		fk := n.NubanBankID
		node, ok := nodeids[fk]
		if !ok {
			return fmt.Errorf(`unexpected referenced foreign-key "nuban_bank_id" returned %v for node %v`, fk, n.ID)
		}
		assign(node, n)
	}
	return nil
}

func (nbq *NubanBankQuery) sqlCount(ctx context.Context) (int, error) {
	_spec := nbq.querySpec()
	if len(nbq.modifiers) > 0 {
		_spec.Modifiers = nbq.modifiers
	}
	_spec.Node.Columns = nbq.ctx.Fields
	if len(nbq.ctx.Fields) > 0 {
		_spec.Unique = nbq.ctx.Unique != nil && *nbq.ctx.Unique
	}
	return sqlgraph.CountNodes(ctx, nbq.driver, _spec)
}

func (nbq *NubanBankQuery) querySpec() *sqlgraph.QuerySpec {
	_spec := sqlgraph.NewQuerySpec(nubanbank.Table, nubanbank.Columns, sqlgraph.NewFieldSpec(nubanbank.FieldID, field.TypeString))
	_spec.From = nbq.sql
	if unique := nbq.ctx.Unique; unique != nil {
		_spec.Unique = *unique
	} else if nbq.path != nil {
		_spec.Unique = true
	}
	if fields := nbq.ctx.Fields; len(fields) > 0 {
		_spec.Node.Columns = make([]string, 0, len(fields))
		_spec.Node.Columns = append(_spec.Node.Columns, nubanbank.FieldID)
		for i := range fields {
			if fields[i] != nubanbank.FieldID {
				_spec.Node.Columns = append(_spec.Node.Columns, fields[i])
			}
		}
	}
	if ps := nbq.predicates; len(ps) > 0 {
		_spec.Predicate = func(selector *sql.Selector) {
			for i := range ps {
				ps[i](selector)
			}
		}
	}
	if limit := nbq.ctx.Limit; limit != nil {
		_spec.Limit = *limit
	}
	if offset := nbq.ctx.Offset; offset != nil {
		_spec.Offset = *offset
	}
	if ps := nbq.order; len(ps) > 0 {
		_spec.Order = func(selector *sql.Selector) {
			for i := range ps {
				ps[i](selector)
			}
		}
	}
	return _spec
}

func (nbq *NubanBankQuery) sqlQuery(ctx context.Context) *sql.Selector {
	builder := sql.Dialect(nbq.driver.Dialect())
	t1 := builder.Table(nubanbank.Table)
	columns := nbq.ctx.Fields
	if len(columns) == 0 {
		columns = nubanbank.Columns
	}
	selector := builder.Select(t1.Columns(columns...)...).From(t1)
	if nbq.sql != nil {
		selector = nbq.sql
		selector.Select(selector.Columns(columns...)...)
	}
	if nbq.ctx.Unique != nil && *nbq.ctx.Unique {
		selector.Distinct()
	}
	for _, m := range nbq.modifiers {
		m(selector)
	}
	for _, p := range nbq.predicates {
		p(selector)
	}
	for _, p := range nbq.order {
		p(selector)
	}
	if offset := nbq.ctx.Offset; offset != nil {
		// limit is mandatory for offset clause. We start
		// with default value, and override it below if needed.
		selector.Offset(*offset).Limit(math.MaxInt32)
	}
	if limit := nbq.ctx.Limit; limit != nil {
		selector.Limit(*limit)
	}
	return selector
}

// ForUpdate locks the selected rows against concurrent updates, and prevent them from being
// updated, deleted or "selected ... for update" by other sessions, until the transaction is
// either committed or rolled-back.
func (nbq *NubanBankQuery) ForUpdate(opts ...sql.LockOption) *NubanBankQuery {
	if nbq.driver.Dialect() == dialect.Postgres {
		nbq.Unique(false)
	}
	nbq.modifiers = append(nbq.modifiers, func(s *sql.Selector) {
		s.ForUpdate(opts...)
	})
	return nbq
}

// ForShare behaves similarly to ForUpdate, except that it acquires a shared mode lock
// on any rows that are read. Other sessions can read the rows, but cannot modify them
// until your transaction commits.
func (nbq *NubanBankQuery) ForShare(opts ...sql.LockOption) *NubanBankQuery {
	if nbq.driver.Dialect() == dialect.Postgres {
		nbq.Unique(false)
	}
	nbq.modifiers = append(nbq.modifiers, func(s *sql.Selector) {
		s.ForShare(opts...)
	})
	return nbq
}

// NubanBankGroupBy is the group-by builder for NubanBank entities.
type NubanBankGroupBy struct {
	selector
	build *NubanBankQuery
}

// Aggregate adds the given aggregation functions to the group-by query.
func (nbgb *NubanBankGroupBy) Aggregate(fns ...AggregateFunc) *NubanBankGroupBy {
	nbgb.fns = append(nbgb.fns, fns...)
	return nbgb
}

// Scan applies the selector query and scans the result into the given value.
func (nbgb *NubanBankGroupBy) Scan(ctx context.Context, v any) error {
	ctx = setContextOp(ctx, nbgb.build.ctx, ent.OpQueryGroupBy)
	if err := nbgb.build.prepareQuery(ctx); err != nil {
		return err
	}
	return scanWithInterceptors[*NubanBankQuery, *NubanBankGroupBy](ctx, nbgb.build, nbgb, nbgb.build.inters, v)
}

func (nbgb *NubanBankGroupBy) sqlScan(ctx context.Context, root *NubanBankQuery, v any) error {
	selector := root.sqlQuery(ctx).Select()
	aggregation := make([]string, 0, len(nbgb.fns))
	for _, fn := range nbgb.fns {
		aggregation = append(aggregation, fn(selector))
	}
	if len(selector.SelectedColumns()) == 0 {
		columns := make([]string, 0, len(*nbgb.flds)+len(nbgb.fns))
		for _, f := range *nbgb.flds {
			columns = append(columns, selector.C(f))
		}
		columns = append(columns, aggregation...)
		selector.Select(columns...)
	}
	selector.GroupBy(selector.Columns(*nbgb.flds...)...)
	if err := selector.Err(); err != nil {
		return err
	}
	rows := &sql.Rows{}
	query, args := selector.Query()
	if err := nbgb.build.driver.Query(ctx, query, args, rows); err != nil {
		return err
	}
	defer rows.Close()
	return sql.ScanSlice(rows, v)
}

